const target = $('Fetch Target').item.json[0] || {};
const speakers = $('Brave Past Speakers').item.json?.web?.results || [];
const audience = $('Brave Audience CFP').item.json?.web?.results || [];
let ventures = [];
try { ventures = $('Fetch Ventures').item.json || []; } catch (e) { ventures = []; }
if (!Array.isArray(ventures)) ventures = [ventures];
const research = {
  target,
  ventures,
  brave_past_speakers: speakers.slice(0, 5).map(r => ({ title: r.title, desc: r.description, url: r.url })),
  brave_audience_cfp: audience.slice(0, 5).map(r => ({ title: r.title, desc: r.description, url: r.url })),
};
return [{ json: research }];

const item = $input.first();
const blocks = item.json.content || [];
const text = blocks.map(b => b.text || '').join('\n').trim();
let parsed = null;
try {
  const a = text.indexOf('{');
  const b = text.lastIndexOf('}');
  if (a >= 0 && b > a) parsed = JSON.parse(text.slice(a, b + 1));
} catch (e) { parsed = null; }
if (!parsed) {
  return [{ json: { error: 'Sonnet returned no parseable JSON', raw: text.slice(0, 500) } }];
}
const src = $('Fetch Target').item.json[0];
const prev = src.enrichment_version || 0;
const clean = s => typeof s === 'string' ? s.replace(/\u2014|\u2013/g, ',') : s;
for (const k of Object.keys(parsed)) {
  if (typeof parsed[k] === 'string') parsed[k] = clean(parsed[k]);
}
if (parsed.proposed_talk?.abstract) parsed.proposed_talk.abstract = clean(parsed.proposed_talk.abstract);
if (parsed.proposed_talk?.title) parsed.proposed_talk.title = clean(parsed.proposed_talk.title);
if (parsed.strategic_value) parsed.strategic_value = clean(parsed.strategic_value);
if (parsed.angle) parsed.angle = clean(parsed.angle);
if (parsed.risk_notes) parsed.risk_notes = clean(parsed.risk_notes);
if (Array.isArray(parsed.next_actions)) parsed.next_actions = parsed.next_actions.map(a => typeof a === 'string' ? clean(a) : a);
return [{ json: { id: src.id, enrichment_version: prev + 1, ...parsed } }];
